'use client'
import React from 'react'

interface WantedStarsHUDProps {
    count?: number
    flashing?: boolean
    size?: number
    className?: string
}

export default function WantedStarsHUD({
    count = 5,
    flashing = false,
    size = 20,
    className = '',
}: WantedStarsHUDProps) {
    return (
        <div
            className={`flex items-center gap-1.5 ${className}`}
            style={{ filter: 'drop-shadow(0 2px 6px rgba(0,0,0,0.8))' }}
        >
            {[0, 1, 2, 3, 4].map((i) => {
                const isFilled = i < count
                return (
                    <svg
                        key={i}
                        width={size}
                        height={size}
                        viewBox="0 0 72 72"
                        className={flashing && isFilled ? 'gta-wanted-flash' : ''}
                    >
                        <polygon
                            points="36,4 44,28 70,28 49,44 57,68 36,52 15,68 23,44 2,28 28,28"
                            fill={isFilled ? '#f5a623' : 'rgba(255, 255, 255, 0.15)'}
                            stroke={isFilled ? '#ffffff' : 'rgba(255, 255, 255, 0.3)'}
                            strokeWidth="2"
                            style={{
                                filter: isFilled
                                    ? 'drop-shadow(0 0 4px rgba(245,166,35,0.8))'
                                    : 'none',
                            }}
                        />
                    </svg>
                )
            })}
        </div>
    )
}
