'use client'
import React, { useEffect, useRef } from 'react'
import gsap from 'gsap'
import { MissionResultProps } from '@/lib/types'
import WantedStarsHUD from './WantedStarsHUD'

interface ConfigItem {
    color: string
    line1: string
    line2: string
    isPassed: boolean
    stat1: string
    stat2: string
}

const CONFIGS: Record<string, ConfigItem> = {
    'passed-access': {
        color: '#66CC66',
        line1: 'MISSION PASSED',
        line2: 'ACCESS GRANTED',
        isPassed: true,
        stat1: 'RESPECT +',
        stat2: 'CLASSIFIED CLEARANCE: UNLOCKED',
    },
    'passed-portfolio': {
        color: '#66CC66',
        line1: 'MISSION PASSED',
        line2: 'PORTFOLIO LOADED',
        isPassed: true,
        stat1: 'INTEL + 100',
        stat2: 'ALL REPOSITORIES UNLOCKED',
    },
    'failed-denied': {
        color: '#cc0000',
        line1: 'MISSION FAILED',
        line2: 'ACCESS DENIED',
        isPassed: false,
        stat1: 'CLEARANCE: REJECTED',
        stat2: 'FALLBACK ROUTE ENGAGED',
    },
    'failed-redirect': {
        color: '#cc0000',
        line1: 'MISSION FAILED',
        line2: 'REDIRECTING TO INTEL\u2026',
        isPassed: false,
        stat1: 'SESSION ABORTED',
        stat2: 'RE-ROUTING TO LOS SANTOS',
    },
}

export default function MissionResult({ type, onComplete, sounds }: MissionResultProps) {
    const overlayRef = useRef<HTMLDivElement | null>(null)
    const flashRef = useRef<HTMLDivElement | null>(null)
    const headlineRef = useRef<HTMLHeadingElement | null>(null)
    const subtitleRef = useRef<HTMLParagraphElement | null>(null)
    const statsRef = useRef<HTMLDivElement | null>(null)
    const contentRef = useRef<HTMLDivElement | null>(null)
    const cfg = (type && CONFIGS[type]) || CONFIGS['passed-access']

    useEffect(() => {
        try {
            if (sounds) {
                if (cfg.isPassed) {
                    sounds.passed?.play()
                } else {
                    sounds.failed?.play()
                }
            }
        } catch (e) {
            console.warn('Audio notice in mission result:', e)
        }

        const tl = gsap.timeline({ onComplete })

        // Intense Entry Flash
        if (flashRef.current) {
            tl.fromTo(
                flashRef.current,
                { opacity: 0.9, backgroundColor: cfg.color },
                { opacity: 0, duration: 0.38, ease: 'power2.out' }
            )
        }

        // Background Dim
        if (overlayRef.current) {
            tl.to(overlayRef.current, { backgroundColor: 'rgba(0,0,0,0.92)', duration: 0.35 }, '-=0.3')
        }

        // Headline SLAM with scale
        if (headlineRef.current) {
            tl.fromTo(
                headlineRef.current,
                { scale: 2.5, opacity: 0 },
                {
                    scale: 1,
                    opacity: 1,
                    duration: 0.45,
                    ease: 'expo.out',
                    onStart: () => {
                        if (contentRef.current) {
                            gsap.fromTo(
                                contentRef.current,
                                { y: -12 },
                                { y: 0, duration: 0.08, repeat: 4, yoyo: true }
                            )
                        }
                    },
                },
                '-=0.25'
            )
        }

        // Subtitle Delay
        if (subtitleRef.current) {
            tl.fromTo(
                subtitleRef.current,
                { opacity: 0, y: 15 },
                { opacity: 1, y: 0, duration: 0.4, ease: 'power2.out' },
                '-=0.15'
            )
        }

        // Stats delay
        if (statsRef.current) {
            tl.fromTo(
                statsRef.current,
                { opacity: 0, scale: 0.9 },
                { opacity: 1, scale: 1, duration: 0.35, ease: 'back.out(1.5)' },
                '+=0.1'
            )
        }

        tl.to({}, { duration: 2.4 })
        if (overlayRef.current) {
            tl.to(overlayRef.current, { opacity: 0, duration: 0.7, ease: 'power2.inOut' })
        }

        return () => {
            tl.kill()
            if (overlayRef.current) gsap.killTweensOf(overlayRef.current)
            if (flashRef.current) gsap.killTweensOf(flashRef.current)
            if (headlineRef.current) gsap.killTweensOf(headlineRef.current)
            if (subtitleRef.current) gsap.killTweensOf(subtitleRef.current)
            if (statsRef.current) gsap.killTweensOf(statsRef.current)
            if (contentRef.current) gsap.killTweensOf(contentRef.current)
        }
    }, [cfg, onComplete, sounds])

    return (
        <div
            ref={overlayRef}
            style={{
                position: 'fixed',
                inset: 0,
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                zIndex: 9000,
                userSelect: 'none',
            }}
        >
            <div
                ref={flashRef}
                style={{
                    position: 'absolute',
                    inset: 0,
                    zIndex: 9001,
                    pointerEvents: 'none',
                }}
            />
            <div className="noise-overlay" />
            <div className="crt-scanlines" />

            {/* Top and Bottom Letterbox Bars */}
            <div
                style={{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    right: 0,
                    height: '60px',
                    background: '#000',
                    borderBottom: `2px solid ${cfg.color}`,
                    zIndex: 9002,
                }}
            />
            <div
                style={{
                    position: 'absolute',
                    bottom: 0,
                    left: 0,
                    right: 0,
                    height: '60px',
                    background: '#000',
                    borderTop: `2px solid ${cfg.color}`,
                    zIndex: 9002,
                }}
            />

            <div ref={contentRef} style={{ textAlign: 'center', zIndex: 9003, padding: '0 24px' }}>
                <div style={{ marginBottom: '16px', display: 'flex', justifyContent: 'center' }}>
                    <WantedStarsHUD count={cfg.isPassed ? 5 : 2} flashing={!cfg.isPassed} size={24} />
                </div>

                <h1
                    ref={headlineRef}
                    className="mission-headline"
                    style={{
                        fontFamily: 'ChaletLondon1960, "Bebas Neue", Montserrat, sans-serif',
                        letterSpacing: '0.05em',
                        textTransform: 'uppercase',
                        color: cfg.color,
                        lineHeight: 1,
                        marginBottom: 12,
                        textShadow: `0 0 40px ${cfg.color}, 0 8px 30px rgba(0,0,0,0.95)`,
                    }}
                >
                    {cfg.line1}
                </h1>

                <p
                    ref={subtitleRef}
                    className="mission-subtitle"
                    style={{
                        fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                        letterSpacing: '0.4em',
                        textTransform: 'uppercase',
                        color: '#ffffff',
                        opacity: 0,
                        textShadow: '0 2px 12px rgba(0,0,0,0.9)',
                        marginBottom: '24px',
                    }}
                >
                    {cfg.line2}
                </p>

                {/* Extra GTA Stats readout */}
                <div
                    ref={statsRef}
                    style={{
                        opacity: 0,
                        display: 'inline-flex',
                        flexDirection: 'column',
                        gap: '6px',
                        background: 'rgba(0, 0, 0, 0.75)',
                        border: '1px solid rgba(255, 255, 255, 0.2)',
                        padding: '10px 28px',
                        fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                        letterSpacing: '0.25em',
                        textTransform: 'uppercase',
                        color: '#ffffff',
                        fontSize: '0.95rem',
                    }}
                >
                    <div style={{ color: cfg.color, fontWeight: 'bold' }}>{cfg.stat1}</div>
                    <div style={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.8rem' }}>{cfg.stat2}</div>
                </div>
            </div>
        </div>
    )
}
